  ('quest', 'daily_blazes', '{"id":"daily_blazes","name":"<red>Fire Fighter","icon":"minecraft:blaze_rod","difficulty":"hard","pool":"daily","objectives":{"kill_blazes":{"type":"kill_mob","display":"<status> Slay <required> blazes in the Nether <aqua><current>/<required>","amount":5,"entities":["minecraft:blaze"],"filters":{"worlds":{"mode":"whitelist","values":["world_nether"]}}}},"rewards":[{"type":"item","item":"minecraft:diamond"}]}', 1, 1792231200000, 'seed', 'server', 'local'),
