  ('quest', 'first_steps', '{"id":"first_steps","name":"<green>First Steps","description":["<gray>Every journey starts with a tree."],"icon":"minecraft:oak_sapling","difficulty":"easy","pool":"global","auto_start":true,"objectives":{"chop_logs":{"type":"block_break","display":"<status> Chop <required> logs <aqua><current>/<required>","amount":8,"blocks":["#minecraft:logs"]},"craft_table":{"type":"craft","display":"<status> Craft a crafting table","amount":1,"stage":1,"items":["minecraft:crafting_table"]}},"rewards":[{"type":"item","item":"minecraft:bread","amount":5},{"type":"message","text":"<green>Well done. The mines are waiting."}],"messages":{"complete":"<green>You took your first steps!"}}', 1, 1792231200000, 'seed', 'server', 'local'),
  ('quest', 'into_the_mines', '{"id":"into_the_mines","name":"<gray>Into the Mines","description":["<gray>The smith needs ore. Lots of it."],"icon":"minecraft:iron_pickaxe","difficulty":"medium","pool":"global","hidden_until_unlocked":true,"requirements":[{"type":"quest_completed","quest":"first_steps"}],"objectives":{"mine_coal":{"type":"block_break","display":"<status> Mine <required> coal ore <aqua><current>/<required>","amount":16,"blocks":["minecraft:coal_ore","minecraft:deepslate_coal_ore"]},"mine_iron":{"type":"block_break","display":"<status> Mine <required> iron ore below Y 64 <aqua><current>/<required>","amount":8,"blocks":["minecraft:iron_ore","minecraft:deepslate_iron_ore"],"filters":{"y":{"max":64}}},"deliver_iron":{"type":"deliver","display":"<status> Bring <required> raw iron <aqua><current>/<required>","amount":8,"stage":1,"items":["minecraft:raw_iron"]}},"rewards":[{"type":"item","item":"minecraft:iron_pickaxe"},{"type":"vanilla_experience","amount":100}]}', 1, 1792231200000, 'seed', 'server', 'local'),
  ('quest', 'trader_errand', '{"id":"trader_errand","name":"<yellow>Trader''s Errand","description":["<gray>The trader always wants more wheat."],"icon":"minecraft:wheat","difficulty":"easy","pool":"global","repeatable":true,"cooldown":"1d","requirements":[{"type":"quest_completed","quest":"first_steps"}],"objectives":{"bring_wheat":{"type":"deliver","display":"<status> Bring <required> wheat <aqua><current>/<required>","amount":32,"items":["minecraft:wheat"]}},"rewards":[{"type":"item","item":"minecraft:emerald","amount":2}]}', 1, 1792231200000, 'seed', 'server', 'local'),
