  ('quest', 'weekly_explorer', '{"id":"weekly_explorer","name":"<gold>Long Walk","icon":"minecraft:leather_boots","difficulty":"hard","pool":"weekly","time_limit":"2d","objectives":{"walk":{"type":"travel_distance","display":"<status> Walk <required> blocks <aqua><current>/<required>","amount":10000,"mode":"walk"}},"rewards":[{"type":"item","item":"minecraft:diamond","amount":3},{"type":"command","run":"say <player> walked 10 kilometres this week!"}]}', 1, 1792231200000, 'seed', 'server', 'local'),
  ('quest', 'hunters_vow', '{"id":"hunters_vow","name":"<red>Hunter''s Vow","description":["<gray>Clear the caves without dying, <player>."],"icon":"minecraft:iron_sword","difficulty":"hard","pool":"global","repeatable":true,"cooldown":"12h","time_limit":"1h","requirements":[{"type":"quest_completed","quest":"first_steps","display":"<gray>Finish First Steps"},{"type":"permission","node":"chronos.quests.hunter","display":"<gray>Rank <gold>Hunter"}],"objectives":{"kill_spiders":{"type":"kill_mob","display":"<status> Slay <required> cave spiders <aqua><current>/<required>","amount":10,"entities":["minecraft:cave_spider"],"filters":{"worlds":{"mode":"whitelist","values":["world"]},"hand":["#minecraft:swords"],"y":{"max":40}}},"bring_eyes":{"type":"deliver","display":"<status> Bring <required> spider eyes <aqua><current>/<required>","amount":5,"stage":1,"items":["minecraft:spider_eye"]}},"rewards":[{"type":"item","item":"minecraft:diamond","amount":2},{"type":"command","run":"say <player> kept the vow","display":"<gold>A shout-out in chat"}],"messages":{"start":"<prefix><red>The vow is sworn. Don''t die."},"fail":{"when":[{"type":"death","display":"Die","amount":1}],"result":"cooldown","cooldown":"1h","message":"<prefix><red>You broke the vow. Try again in an hour."},"notices":{"complete":{"title":{"subtitle":"<yellow>The vow is kept, <player>"}}}}', 1, 1792231200000, 'seed', 'server', 'local'),
  ('quest', 'hydras_bane', '{"id":"hydras_bane","name":"<gradient:#3a2a24:#ff7a1c>The Cinder Hydra</gradient>","description":["<gray>Something burns beneath the <gold>Ashen Peaks</gold>.","<gray>Bring friends. <italic>Lots</italic> of friends."],"icon":"minecraft:dragon_head","difficulty":"hard","pool":"boss_hunts","repeatable":true,"cooldown":"3d","time_limit":"1h","requirements":[{"type":"quest_completed","quest":"hunters_vow"},{"type":"level","min":20},{"type":"tyche_boss_kills","boss":"cinder_hydra","compare":"<","value":10},{"type":"has_vulcan_item","item":"vulcan:ember_blade"}],"objectives":{"whelps":{"type":"kill_tyche_mob","amount":15,"mobs":["ember_whelp"],"summoned_by":["cinder_hydra"]},"heads":{"type":"damage_tyche","amount":20,"bosses":["cinder_hydra"],"parts":["b_head_left","b_head_right"],"count":"hits"},"slay":{"type":"kill_tyche_boss","amount":1,"stage":1,"bosses":["cinder_hydra"],"credit":"contributors","min_share":10,"max_fight":"5m"}},"rewards":[{"type":"coins","amount":500},{"type":"coins","amount":5,"currency":"gems","reason":"Hydra''s hoard"},{"type":"tyche_loot","table":"hydra_hoard","rolls":2},{"type":"vulcan_item","item":"vulcan:ember_crown","quality":"random"},{"type":"experience","amount":250},{"type":"broadcast","text":"<gold><player> <yellow>slew the Cinder Hydra!"},{"type":"command","run":"lp user <player> parent add hydra_slayer","display":"<gold>The <red>Hydra Slayer</red> title"}],"messages":{"start":"<prefix><red>The peaks tremble."},"fail":{"when":[{"type":"killed_by_tyche","display":"<red>Burn in its flame breath","amount":1,"bosses":["cinder_hydra"],"attacks":["flame_breath"]},{"type":"damaged_by_tyche","amount":3,"summoned_by":["cinder_hydra"],"count":"hits"}],"unless":[{"type":"in_world","worlds":["world"]},{"type":"health","compare":">","value":4}],"result":"cooldown","cooldown":"1h","message":"<red>The hydra sends you home. Try again in an hour."}}', 1, 1792231200000, 'seed', 'server', 'local'),
  ('quest', 'old_roads', '{"id":"old_roads","name":"<aqua>Old Roads","description":["<gray>One map for all your characters."],"icon":"minecraft:filled_map","difficulty":"easy","pool":"global","scope":"account","objectives":{"walk":{"type":"travel_distance","display":"<status> Walk <required> blocks <aqua><current>/<required>","amount":5000,"mode":"walk"}},"rewards":[{"type":"vanilla_experience","amount":100}]}', 1, 1792231200000, 'seed', 'server', 'local'),
  ('quest', 'legacy_dragon', '{"id":"legacy_dragon","name":"<light_purple>Dragon Slayer","icon":"minecraft:dragon_head","difficulty":"hard","pool":"legacy","objectives":{"kill_dragon":{"type":"kill_mob","display":"<status> Slay the Ender Dragon <aqua><current>/<required>","amount":1,"entities":["minecraft:ender_dragon"]}},"rewards":[{"type":"item","item":"minecraft:elytra"}]}', 1, 1792231200000, 'seed', 'server', 'local'),
  ('quest', 'smiths_favour', '{"id":"smiths_favour","name":"<#c9d1d9>The Smith''s <bold>Favour","description":["<gray>The smith is grumpy on weekends.<newline><dark_gray>Bring a book or two."],"icon":"minecraft:anvil","pool":"global","requirements":[{"type":"real_time","days":["saturday","sunday"]},{"type":"vanilla_level","value":10}],"objectives":{"talk_to_smith":{"type":"custom","display":"<status> Talk to the smith in town","amount":1},"smelt_iron":{"type":"smelt","amount":32,"stage":1,"items":["minecraft:iron_ingot"]},"books":{"type":"trade","amount":5,"stage":1,"items":["minecraft:enchanted_book"],"professions":["librarian"]}},"rewards":[{"type":"items","items":["minecraft:bread","minecraft:apple"],"amount":5},{"type":"vanilla_levels","amount":5},{"type":"potion_effect","potion":"regeneration","level":2,"duration":"1m"},{"type":"start_quest","quest":"hunters_vow"}]}', 1, 1792231200000, 'seed', 'server', 'local');
